function zoneOf(p){const x=+p.x,y=+p.y;if(y<.28&&Math.abs(x-.5)<.24)return 'Cerca del aro';if(y<.5&&Math.abs(x-.5)<.3)return 'Pintura';if((x<.18||x>.82)&&y<.55)return 'Esquina';if(y>.58)return 'Triple frontal/lateral';return 'Media distancia'}
