  openModal('Temporada',mode==='defense'?'Mapa de calor · defensa':mode==='both'?'Ataque frente a defensa':'Mapa de calor · ataque',`<div class="map-switch"><button class="${mode==='attack'?'active':''}" data-action="heat-mode" data-mode="attack">Ataque</button><button class="${mode==='defense'?'active':''}" data-action="heat-mode" data-mode="defense">Defensa</button><button class="${mode==='both'?'active':''}" data-action="heat-mode" data-mode="both">Juntos</button></div><div class="map-legend" style="margin-top:9px"><span class="own">● Ataque · dónde metemos</span><span class="against">● Defensa · dónde nos meten</span></div><div class="grid" style="margin-top:12px"><div class="span-6"><div class="field"><label>Filtrar rival</label><select id="heatOpponent"><option value="">Toda la temporada</option>${games.filter(g=>(g.shotsFor?.length||g.shotsAgainst?.length)).map(g=>`<option value="${g.id}">${esc(g.opponent)}</option>`).join('')}</select></div></div><div class="span-6"><div class="field"><label>Condición</label><select id="heatHome"><option value="all">Casa y fuera</option><option value="home">Casa</option><option value="away">Fuera</option></select></div></div></div><div id="heatContent"></div><div class="notice"><b>${mode==='defense'?'Dónde nos meten':'Dónde metemos'}.</b> Las cifras son reparto de canastas anotadas por zona, nunca porcentaje de acierto. El filtro por cuarto solo aparece si los puntos importados incluyen cuarto.</div>`);renderHeatFiltered();
