  const g=games.find(x=>x.id===gameId)||games.find(x=>x.shotsFor?.length||x.shotsAgainst?.length)||games[0];modalContext={type:'shot',gameId:g.id,shotsFor:[...(g.shotsFor||[])],shotsAgainst:[...(g.shotsAgainst||[])],kind:'for',selected:''};
  const body=`<div class="field"><label>Partido</label><select id="shotGame">${games.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${esc(x.opponent)}</option>`).join('')}</select></div><div class="grid"><div class="span-4"><div class="field"><label>Buen Consejo aparece</label><select id="shotSide"><option value="left" ${state.settings.shotSide==='left'?'selected':''}>en la mitad izquierda</option><option value="right" ${state.settings.shotSide==='right'?'selected':''}>en la mitad derecha</option><option value="auto" ${state.settings.shotSide==='auto'?'selected':''}>que lo identifique la IA</option></select></div></div><div class="span-4"><div class="field"><label>Color de Buen Consejo</label><input id="shotColor" value="${esc(state.settings.shotColor||'por confirmar')}" placeholder="rojo, gris… o por confirmar"></div></div><div class="span-4"><div class="field"><label>Color del rival</label><input id="rivalColor" value="${esc(state.settings.rivalColor||'por confirmar')}" placeholder="gris, rojo…"></div></div></div><div class="action-row"><button class="btn" data-action="copy-shot-prompt">Copiar prompt para mi IA</button><button class="btn" data-action="show-shot-json">Pegar respuesta JSON</button></div><p class="notice"><b>Flexible por partido.</b> La IA debe identificar a Buen Consejo usando nombre, marcador, color y lado visibles. Antes de guardar, confirma o intercambia con un toque qué lista es «nuestra» y cuál «del rival».</p><div id="shotAssignment"></div><div class="court-wrap"><div id="shotCourt">${courtHTML(modalContext.shotsFor,modalContext.shotsAgainst,false,modalContext.selected)}</div><div><h3>Revisar y corregir</h3><div class="shot-kind"><button class="active" data-action="shot-kind" data-kind="for">● Nuestra (ataque)</button><button data-action="shot-kind" data-kind="against">● Rival (defensa)</button></div><p class="muted">Toca para añadir. Arrastra un punto para moverlo; selecciónalo y pulsa borrar.</p><div class="action-row"><button class="btn" data-action="swap-shot-teams">Intercambiar equipos</button><button class="btn ghost danger" data-action="delete-selected-shot">Borrar punto</button><button class="btn ghost danger" data-action="clear-shots">Vaciar todo</button></div><button class="btn primary" data-action="save-shots">Guardar ambos mapas</button><div id="shotJsonWrap" hidden><div class="field" style="margin-top:10px"><label>Respuesta exacta de la IA</label><textarea id="shotJson" rows="7" placeholder='{"court":"half","ownIdentification":{"team":"BUEN CONSEJO","side":"left","color":"red"},"opponentIdentification":{"team":"RIVAL","side":"right","color":"gray"},"ownShots":[{"x":0.42,"y":0.18}],"opponentShots":[{"x":0.55,"y":0.22}]}'></textarea></div><button class="btn" data-action="apply-shot-json">Colocar las dos listas</button></div></div></div>`;
