function finishLive(){const L=state.live;const match=bestGameMatch(L);if(match){match.events=[...(match.events||[]),...L.events.filter(e=>!e.undone)];match.availability={...(match.availability||{}),manual:true};record('replace-game',{game:match});state.live=null;save();record('live-upsert',{live:null});toast('Directo unido al acta de '+match.opponent);setView('games')}else{openModal('Guardar Directo','Falta el acta FBM',`<p>Las acciones quedan guardadas. Cuando importes el acta, la app buscará por rival y fecha.</p><button class="btn primary" data-action="keep-live-pending">Guardar pendiente</button>`)}}
function bestGameMatch(L){const words=new Set(norm(L.opponent).split(' '));let best=null,score=0;state.games.forEach(g=>{const w=norm(g.opponent).split(' '),s=w.filter(x=>words.has(x)).length/Math.max(words.size,w.length)+(g.date===L.date?.5:0);if(s>score){score=s;best=g}});return score>.35?best:null}
function keepLivePending(){state.games.push({id:uid(),opponent:state.live.opponent,date:state.live.date,home:true,us:null,them:null,players:[],events:state.live.events.filter(e=>!e.undone),shotsFor:[],shotsAgainst:[],source:'live-pending',availability:{manual:true,boxscore:false,shotMap:false}});record('replace-game',{game:state.games.at(-1)});state.live=null;save();record('live-upsert',{live:null});closeModal();setView('games')}

function openSettings(){openModal('Aplicación','Ajustes y sincronización',`<div class="field"><label>URL del Worker</label><input id="apiUrl" value="${esc(state.settings.api)}" placeholder="https://estadisticas.tu-subdominio.workers.dev"></div><div class="field"><label>Token del enlace</label><input id="apiToken" value="${esc(state.settings.token)}"></div><div class="field"><label>Permiso</label><select id="apiRole"><option value="admin" ${state.settings.role==='admin'?'selected':''}>Administrador</option><option value="editor" ${state.settings.role==='editor'?'selected':''}>Editor</option><option value="viewer" ${state.settings.role==='viewer'?'selected':''}>Solo lectura</option></select></div><div class="action-row"><button class="btn primary" data-action="save-settings">Guardar y sincronizar</button><button class="btn" data-action="export-json">Exportar copia</button></div>${state.settings.role==='admin'&&state.settings.api?`<div class="card" style="margin-top:12px"><div class="card-head"><div><h3>Compartir</h3><p>Crea un enlace individual y revócalo cuando quieras</p></div></div><div class="field"><label>Nombre del enlace</label><input id="inviteLabel" placeholder="Ej.: María · mesa"></div><div class="action-row"><button class="btn" data-action="create-invite" data-role="editor">Crear enlace de edición</button><button class="btn" data-action="create-invite" data-role="viewer">Crear enlace de lectura</button></div><div id="inviteResult"></div></div>`:''}<div class="notice"><b>Privacidad:</b> todos los usuarios del equipo comparten los mismos datos. El token determina si pueden editar o solo ver.</div>`)}
function saveSettings(){state.settings.api=$('#apiUrl').value.trim().replace(/\/$/,'');state.settings.token=$('#apiToken').value.trim();state.settings.role=$('#apiRole').value;save();closeModal();syncNow();render()}
async function createInvite(role){try{const r=await fetch(state.settings.api+'/api/invites',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.settings.token},body:JSON.stringify({role,label:$('#inviteLabel')?.value||''})});const j=await r.json();if(!r.ok)throw Error(j.error||'No se pudo crear');const link=location.origin+location.pathname+'?api='+encodeURIComponent(state.settings.api)+'&token='+encodeURIComponent(j.token)+'&role='+role;$('#inviteResult').innerHTML=`<div class="field" style="margin-top:10px"><label>Enlace ${role==='editor'?'de edición':'de lectura'}</label><textarea id="inviteLink" rows="3" readonly>${esc(link)}</textarea></div><button class="btn small" data-action="copy-invite">Copiar enlace</button>`}catch(e){toast(e.message)}}
let syncing=false,syncTimer;
function scheduleSync(){clearTimeout(syncTimer);syncTimer=setTimeout(syncNow,700)}
async function syncNow(){if(syncing||!state.settings.api||!state.settings.token)return;syncing=true;paintSync(true);try{if(state.ops.length&&state.settings.role!=='viewer'){const r=await fetch(state.settings.api+'/api/events',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.settings.token},body:JSON.stringify({events:state.ops})});if(!r.ok)throw Error('No se pudo enviar');state.ops=[];save()}const r=await fetch(state.settings.api+'/api/events?since='+state.lastSeq,{headers:{'Authorization':'Bearer '+state.settings.token}});if(!r.ok)throw Error('No se pudo leer');const j=await r.json();(j.events||[]).forEach(applyRemote);state.lastSeq=j.lastSeq||state.lastSeq;save();$('#syncStatus').classList.add('online');render()}catch(e){console.warn(e);$('#syncStatus').classList.remove('online')}finally{syncing=false;paintSync()}}
function applyRemote(row){const o=row.event||row;if(state.ops.some(x=>x.id===o.id))return;const p=o.payload||{};if(o.type==='set-roster')state.roster=mergeRoster(state.roster,p.roster||[]);if(o.type==='replace-game'){const i=state.games.findIndex(g=>g.id===p.game.id);i<0?state.games.push(p.game):state.games[i]=p.game}if(o.type==='live-upsert')state.live=p.live;if(o.type==='live-event'&&state.live?.id===p.liveId&&!state.live.events.some(e=>e.id===p.event.id))state.live.events.push(p.event);if(o.type==='live-undo'&&state.live?.id===p.liveId){const e=state.live.events.find(e=>e.id===p.eventId);if(e)e.undone=true}if(o.type==='shot-set'){const g=state.games.find(g=>g.id===p.gameId);if(g){g.shotsFor=p.shotsFor||[];g.shotsAgainst=p.shotsAgainst||[]}}}
function paintSync(busy=false){const s=$('#syncStatus');if(!s)return;s.querySelector('b').textContent=busy?'Sincronizando…':state.settings.api?'Equipo conectado':'Solo local';s.classList.toggle('online',!!state.settings.api&&!busy)}

async function copyText(s){await navigator.clipboard.writeText(s);toast('Prompt copiado')}
function exportJSON(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='estadisticas-copia-'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}
function install(){if(installPrompt){installPrompt.prompt();installPrompt=null}else openModal('Instalar','Añadir a la pantalla de inicio','<p><b>Android / Chrome:</b> abre el menú ⋮ y toca «Instalar aplicación» o «Añadir a pantalla de inicio».</p><p><b>iPhone / Safari:</b> toca Compartir y después «Añadir a pantalla de inicio».</p>')}

document.addEventListener('click',async e=>{
  const go=e.target.closest('[data-go]');if(go)return setView(go.dataset.go);
  const d=e.target.closest('[data-detail]');if(d)return detail(d.dataset.detail);
  const a=e.target.closest('[data-action]');if(!a)return;const act=a.dataset.action;
  const writeActions=new Set(['import-games','import-roster','confirm-import','start-live','quarter','add-live','pick-live-player','undo-live','finish-live','keep-live-pending','open-shot','shot-for-game','shot-kind','swap-shot-teams','delete-selected-shot','clear-shots','apply-shot-json','save-shots']);if(state.settings.role==='viewer'&&writeActions.has(act))return toast('Este enlace es de solo lectura');
  if(act==='close-modal')return closeModal();if(act==='toggle-theme'){const th=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=th;localStorage.setItem('estadisticas_theme',th);return}if(act==='install')return install();if(act==='open-settings'||act==='open-sync')return openSettings();if(act==='save-settings')return saveSettings();if(act==='export-json')return exportJSON();if(act==='create-invite')return createInvite(a.dataset.role);if(act==='copy-invite')return copyText($('#inviteLink').value);
  if(act==='import-games'||act==='import-roster'){fileMode=act==='import-roster'?'roster':'games';$('#fileInput').value='';return $('#fileInput').click()}if(act==='confirm-import')return commitImport();if(act==='start-live')return startLive();if(act==='quarter'){state.live.quarter=+a.dataset.q;save();record('live-upsert',{live:state.live});return render()}if(act==='add-live')return addLive(a.dataset.type);if(act==='pick-live-player')return commitLiveEvent(a.dataset.type,a.dataset.id);if(act==='undo-live')return undoLive();if(act==='finish-live')return finishLive();if(act==='keep-live-pending')return keepLivePending();
  if(act==='heat-mode')return openHeatAnalysis('heat-'+(a.dataset.mode==='both'?'compare':a.dataset.mode));
  if(act==='game-map-mode'){const g=state.games.find(x=>x.id===a.dataset.id),mode=a.dataset.mode;$$('.map-switch button').forEach(b=>b.classList.toggle('active',b===a));$('#gameMapCourt').innerHTML=courtHTML(mode==='defense'?[]:g.shotsFor||[],mode==='attack'?[]:g.shotsAgainst||[]);return}
  if(act==='open-shot')return openShotDetail();if(act==='shot-for-game')return openShotDetail(a.dataset.id);if(act==='copy-shot-prompt'){state.settings.shotSide=$('#shotSide').value;state.settings.shotColor=$('#shotColor').value;state.settings.rivalColor=$('#rivalColor').value;save();return copyText(shotPrompt())}if(act==='show-shot-json'){return $('#shotJsonWrap').hidden=false}
  if(act==='shot-kind'){modalContext.kind=a.dataset.kind;$$('.shot-kind button').forEach(b=>b.classList.toggle('active',b===a));return}
  if(act==='swap-shot-teams'){[modalContext.shotsFor,modalContext.shotsAgainst]=[modalContext.shotsAgainst,modalContext.shotsFor];modalContext.selected='';repaintShotCourt();return toast('Listas intercambiadas; confirma antes de guardar')}
  if(act==='delete-selected-shot'){if(!modalContext.selected)return toast('Selecciona un punto');const [kind,i]=modalContext.selected.split(':'),arr=kind==='for'?modalContext.shotsFor:modalContext.shotsAgainst;arr.splice(+i,1);modalContext.selected='';repaintShotCourt();return}
  if(act==='clear-shots'){modalContext.shotsFor=[];modalContext.shotsAgainst=[];modalContext.selected='';repaintShotCourt();return}
  if(act==='apply-shot-json'){try{const raw=$('#shotJson').value.replace(/```(?:json)?|```/g,'').trim(),j=JSON.parse(raw);if(!Array.isArray(j.ownShots)||!Array.isArray(j.opponentShots))throw 0;modalContext.shotsFor=foldShots(j.ownShots,j.court||'half',j.ownIdentification?.side||'left');modalContext.shotsAgainst=foldShots(j.opponentShots,j.court||'half',j.opponentIdentification?.side||'right');state.settings.shotSide=j.ownIdentification?.side||$('#shotSide').value;state.settings.shotColor=j.ownIdentification?.color||$('#shotColor').value;state.settings.rivalColor=j.opponentIdentification?.color||$('#rivalColor').value;modalContext.selected='';const ok=j.ownIdentification?.checksAgree!==false&&j.opponentIdentification?.checksAgree!==false;$('#shotAssignment').innerHTML=`<div class="notice" style="border-color:${ok?'var(--good)':'var(--bad)'}"><b>${ok?'Asignación comprobada':'Revisión necesaria'}:</b> Buen Consejo ${esc(j.ownIdentification?.headerPosition||'—')} · mitad ${esc(j.ownIdentification?.side||'—')} · ${esc(j.ownIdentification?.color||'—')}. Rival ${esc(j.opponentIdentification?.headerPosition||'—')} · mitad ${esc(j.opponentIdentification?.side||'—')} · ${esc(j.opponentIdentification?.color||'—')}. ${ok?'Cabecera, color y lista coinciden.':esc(j.ownIdentification?.conflict||j.opponentIdentification?.conflict||'Las comprobaciones no coinciden.')}</div>`;repaintShotCourt();toast(`${modalContext.shotsFor.length} propias y ${modalContext.shotsAgainst.length} rivales`)}catch(x){toast('JSON no válido. Debe incluir ownShots y opponentShots.')}return}
  if(act==='save-shots'){const gid=$('#shotGame').value,g=state.games.find(x=>x.id===gid);g.shotsFor=modalContext.shotsFor;g.shotsAgainst=modalContext.shotsAgainst;g.courtMode='half';g.sourceSide=$('#shotSide').value;g.sourceColor=$('#shotColor').value;g.rivalColor=$('#rivalColor').value;g.availability={...(g.availability||{}),shotMap:g.shotsFor.length>0||g.shotsAgainst.length>0};state.settings.shotSide=g.sourceSide;state.settings.shotColor=g.sourceColor;state.settings.rivalColor=g.rivalColor;save();record('shot-set',{gameId:g.id,shotsFor:g.shotsFor,shotsAgainst:g.shotsAgainst});closeModal();render();return}
});
document.addEventListener('change',e=>{if(e.target.matches('#heatOpponent,#heatHome'))renderHeatFiltered()});
$('#fileInput').addEventListener('change',e=>handleFiles([...e.target.files]));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').hidden)closeModal()});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(console.warn);
const q=new URLSearchParams(location.search);if(q.get('api')&&q.get('token')){state.settings.api=q.get('api');state.settings.token=q.get('token');state.settings.role=q.get('role')||'viewer';save();history.replaceState({},'',location.pathname)}
paintSync();render();if(state.settings.api){syncNow();setInterval(syncNow,5000)}
window.__ESTADISTICAS__={getState:()=>state,setState:s=>{state=sanitise(s);save();render()},foldShots,splitLegacyShots,parseGame,APP_VERSION};
